// A synthetic employee directory. Deterministic on purpose: a demo that returns
// different rows each run is one you cannot rehearse against.
//
// The optional filter arrives as whatever the caller passed; treat it as a
// plain substring match over department and role rather than requiring exact
// syntax, because the caller is a language model and will phrase it freely.
const people = [
  { id: 'E-1001', name: 'Amara Osei',      role: 'Staff SRE',            department: 'Platform',    location: 'Lisbon',    on_call: true,  started: '2021-03-15' },
  { id: 'E-1002', name: 'Ravi Menon',      role: 'Senior SRE',           department: 'Platform',    location: 'Bengaluru', on_call: false, started: '2022-07-04' },
  { id: 'E-1003', name: 'Lena Fischer',    role: 'Platform Engineer',    department: 'Platform',    location: 'Berlin',    on_call: false, started: '2023-01-09' },
  { id: 'E-1004', name: 'Tomas Alvarez',   role: 'Engineering Manager',  department: 'Platform',    location: 'Madrid',    on_call: false, started: '2020-11-02' },
  { id: 'E-2001', name: 'Priya Raghavan',  role: 'Data Engineer',        department: 'Data',        location: 'Bengaluru', on_call: true,  started: '2022-02-21' },
  { id: 'E-2002', name: 'Jonas Lindqvist', role: 'Analytics Engineer',   department: 'Data',        location: 'Stockholm', on_call: false, started: '2023-09-18' },
  { id: 'E-3001', name: 'Mei Tanaka',      role: 'Security Engineer',    department: 'Security',    location: 'Singapore', on_call: true,  started: '2021-06-07' },
  { id: 'E-3002', name: 'Daniel Okafor',   role: 'AppSec Engineer',      department: 'Security',    location: 'Lagos',     on_call: false, started: '2024-04-15' },
  { id: 'E-4001', name: 'Sofia Rossi',     role: 'Product Manager',      department: 'Product',     location: 'Milan',     on_call: false, started: '2022-10-10' },
  { id: 'E-4002', name: 'Noah Bergman',    role: 'Designer',             department: 'Product',     location: 'Oslo',      on_call: false, started: '2023-05-22' },
];

const raw = JSON.stringify($input.first()?.json ?? {}).toLowerCase();
const matched = people.filter((p) =>
  raw.includes(p.department.toLowerCase()) || raw.includes(p.role.toLowerCase()));
// No recognisable filter in the request means "show me everyone".
const rows = matched.length > 0 ? matched : people;

const byDept = {};
for (const p of rows) byDept[p.department] = (byDept[p.department] ?? 0) + 1;

return [{
  json: {
    count: rows.length,
    total_headcount: people.length,
    on_call_now: rows.filter((p) => p.on_call).map((p) => p.name),
    by_department: byDept,
    employees: rows,
  },
}];
